        Person saved = saveUnique(into);
        audit.recordOnCommit("PERSON_MERGED sheet=" + sheetId + " by=" + user.strip()
                + " from=" + from.getName() + " into=" + saved.getName());
        rollup.recordChanges(sheetId, user, before);
        return saved;
